<?php
require_once __DIR__ . '/_layout.php';requirePermission('cash.manage');
if(requestMethod()==='POST'){requireCsrfPost();try{if(($_POST['action']??'')!=='open')throw new InvalidArgumentException(t('validation.invalid_action'));$id=openCashRegister(['agency_id'=>(int)($_POST['agency_id']??0),'business_date'=>$_POST['business_date']??'','opening_balance'=>$_POST['opening_balance']??'','idempotency_key'=>$_POST['idempotency_key']??'']);flash('success',t('message.cash_opened'));safeRedirect('cash_register_detail.php?id='.$id);}catch(AuthorizationException$e){http_response_code(403);exit(t('validation.not_authorized'));}catch(InvalidArgumentException|DomainException$e){flash('danger',$e->getMessage());}catch(Throwable$e){reportDatabaseError($e,'Cash register opening failed');flash('danger',t('message.cash_failed'));}safeRedirect('cash.php');}
[$ids,$ph]=financeScopedPlaceholders(currentAgencyIds());$agencies=dbFetchAll("SELECT id,name FROM agencies WHERE id IN ($ph) AND archived_at IS NULL ORDER BY name",$ids);$registers=dbFetchAll("SELECT cr.*,a.name agency_name FROM cash_registers cr JOIN agencies a ON a.id=cr.agency_id WHERE cr.agency_id IN ($ph) ORDER BY cr.business_date DESC,cr.id DESC LIMIT 100",$ids);backofficeHeader(t('page.cash.title'),'cash.php');pageHeader('page.cash.title','page.cash.description',['breadcrumbs'=>[['label'=>'nav.finance'],['label'=>'nav.cash_register']],'primary'=>['label'=>'action.open_register','href'=>'#new-register']]);?>
<div class="grid"><section class="card" id="new-register"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.open_day'))?></h2></div><form method="post"><?=csrfField()?><?=financeIdempotencyField('cash.open')?><input type="hidden" name="action" value="open"><label><?=e(t('field.agency'))?><select name="agency_id"><?php foreach($agencies as$a):?><option value="<?=e($a['id'])?>"><?=e($a['name'])?></option><?php endforeach;?></select></label><label><?=e(t('field.business_date'))?><input type="date" name="business_date" value="<?=e(date('Y-m-d'))?>" required></label><label><?=e(t('field.opening_balance'))?><input name="opening_balance" value="0.00" type="number" step="0.01" inputmode="decimal" required></label><button class="btn primary"><?=e(t('action.open_register'))?></button></form></section><section class="card"><div class="section-card-header"><h2><?=navigationIcon('finance')?><?=e(t('section.register_history'))?></h2></div><div class="table-wrap"><table><thead><tr><th><?=e(t('field.date'))?></th><th><?=e(t('field.agency'))?></th><th><?=e(t('field.opening'))?></th><th><?=e(t('field.expected'))?></th><th><?=e(t('field.actual'))?></th><th><?=e(t('field.difference'))?></th><th><?=e(t('common.status'))?></th></tr></thead><tbody><?php foreach($registers as$r):?><tr><td><a href="cash_register_detail.php?id=<?=e($r['id'])?>"><?=formattedDate($r['business_date'])?></a></td><td><?=e($r['agency_name'])?></td><td><?=money($r['opening_balance'],$r['currency'])?></td><td><?=money($r['expected_balance']??0,$r['currency'])?></td><td><?=money($r['actual_balance']??0,$r['currency'])?></td><td><?=money($r['difference_amount']??0,$r['currency'])?></td><td><?=statusBadge($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php backofficeFooter();
